export function preloadWalkAssets(scene) {
    WALK_IMAGE_ASSETS.forEach(({ key, path }) => scene.load.image(key, path));
    WALK_SPRITESHEETS.forEach(({ key, path, frameWidth, frameHeight }) => {
        scene.load.spritesheet(key, path, { frameWidth, frameHeight });
    });
    WALK_JSON_ASSETS.forEach(({ key, path }) => scene.load.json(key, path));
}
